{
  "probability": 0.25,
  "range_low": 0.15,
  "range_high": 0.35,
  "summary": [
    "Current forecasts show no consensus for a 2/3 majority; Fidesz still strong but near threshold, with the possibility of opposition consolidation but overall path to 133+ seats is uncertain.",
    "Real-PR seat projections suggest around 127 seats for Fidesz, below 133; polling volatility adds uncertainty.",
    "Historically, 2/3 majorities occurred in roughly 55–60% of post-1990 elections, but current dynamics and district-level math reduce the likelihood.",
    "Bayesian updates from polls, math constraints, and political dynamics yield a calibrated posterior around 0.25 with a moderate uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Starting from a baseline near 0.56 for a 2/3 majority in post-1990 Hungarian elections, multiple updates push the probability down toward 0.25. While opposition consolidation could raise odds, structural seat math and mixed polls keep the forecast uncertain and the supermajority unlikely but nonzero.",
  "justification": {
    "anchor": {
      "probability": 0.56,
      "basis": "Two-thirds majority historically occurred in about 5 of 9 elections since 1990, i.e., roughly 55–60%. This anchors the base rate for a supermajority in a 199-seat parliament."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA leadership",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Consolidation could increase anti-Fidesz vote share and focus votes in key districts, potentially producing more seats for the opposition; however, impact depends on turnout and district-level translation."
      },
      {
        "factor": "District-level seat bias / gerrymandering favorable to opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "If district-level maps and turnout align, a unified opposition could win more seats than national vote share alone would suggest."
      },
      {
        "factor": "Cross-poll signals showing Tisza leads across major polls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Momentum in polls across several institutes could translate into seats in pivotal districts, though not guaranteed."
      },
      {
        "factor": "Two-thirds majority remains hard due to seat math",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Most seat projections place anti-Fidesz around 105–127 seats; 133+ requires a substantial leap, given the electoral system."
      },
      {
        "factor": "EU funding dynamics reducing external pressure",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "A softer external push for regime change could dampen momentum toward a 2/3 majority."
      }
    ],
    "synthesis_rationale": "The base rate is tempered by multiple down-weighting factors (seat math, mixed polls, external constraints) with several up-weighting factors (opposition consolidation, district-level effects, poll momentum). The net calibration yields a 25% posterior with a plausible 15–35% range, reflecting substantial uncertainty."
  }
}

{
