  "range_low": 0.18,
  "range_high": 0.32,
  "summary": [
    "Historical base-rate for 2/3 majorities in post-1990 Hungary is about 44%, used as the anchor.",
    "Real-PR seat projections place a 2/3 threshold around 127 seats—below 133—suggesting a low likelihood of a 2/3 majority under current math.",
    "Opposition consolidation around TISZA and district-level seat dynamics could raise odds in some scenarios, but poll volatility and undecideds keep outcomes uncertain.",
    "Overall, the posterior probability for any party/coalition achieving 2/3 remains 25%, indicating a plausible but unlikely event."
  ],
  "confidence": "low",
  "narrative": "Starting from a historical baseline of roughly 44% for a 2/3 majority, current seat math and mixed polling reduce the odds of achieving 133+ seats. While opposition unity around TISZA and favorable district-level dynamics could help in certain scenarios, overall turnout and polling uncertainty keep a 2/3 majority unlikely, with a posterior around 25%.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate for 2/3 majorities in post-1990 Hungarian elections (approximately 4 of 9 contests)."
    },
    "factor_updates": [
      {
        "factor": "Fidesz seat projection versus 2/3 threshold",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Seat projections around 127 seats fall short of 133, reducing the likelihood of a 2/3 majority."
      },
      {
        "factor": "Opposition consolidation around TISZA leadership (Péter Magyar)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls show TISZA ahead in several surveys; cross-party unity could translate into more seats if turnout cooperates."
      },
      {
        "factor": "District-level seat bias / gerrymandering favorable to opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "District-level math could yield 133+ seats even with weaker national vote share."
      },
      {
        "factor": "Polling volatility and lack of consensus",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent polls across institutes temper confidence in any single outcome; introduces uncertainty."
      },
      {
        "factor": "Historical base-rate for 2/3 majorities",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Provides broad context but not deterministic; used as anchor for calibration."
      },
      {
        "factor": "Economic/market signals of political change",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Markets price in uncertainty about regime change, which can dampen expectations for a 2/3 majority."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the updates tilt both ways but net toward a low-probability 2/3 outcome due to structural seat math and fragmented polls; the posterior 0.25 reflects the balance of evidence and the high uncertainty in turnout and district-level effects."
  }
}

